(function(){
'use strict';
const P=window.ProcedureLogic, SEED=window.PROCEDURE_SEED||[];
const el=document.getElementById('app');
const state={db:null,user:null,demo:false,view:'overview',catalog:[],entries:[],metrics:new Map(),
 search:'',historySearch:'',settingsSearch:'',practiceFilter:'all',expanded:new Set(),detailId:null,
 editEntryId:null,editProcedureId:null,previewMessage:'',preselectedId:null,preselectedKind:null,overviewFilter:'all',busy:false,lastSync:0};
const configured=()=>{const c=window.PROCEDURE_APP_CONFIG||{};return c.supabaseUrl?.startsWith('https://') && !c.supabaseUrl.includes('PASTE_') && c.supabasePublishableKey && !c.supabasePublishableKey.includes('PASTE_')};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>x==null?'—':Number(x).toLocaleString('en-US');
const pct=x=>x==null?'—':(Math.round(x*10)/10).toFixed(x%1===0?0:1)+'%';
const today=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const friendly=x=>x?new Date(x+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Not recorded';
const shortDate=x=>x?new Date(x+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'2-digit'}):'—';
const id=()=>crypto.randomUUID();
const getProc=x=>state.catalog.find(p=>p.id===x);
const isHalo=p=>!!p.halo;
const displayName=p=>p?`${p.procedure_group}${p.variant?' · '+p.variant:''}`:'Deleted procedure';
const categories=()=>[...new Set(state.catalog.filter(p=>p.active).map(p=>p.category))];
const options=list=>list.map(p=>`<option value="${esc(p.id)}">${esc(displayName(p))}</option>`).join('');
const nonSummaries=()=>state.catalog.filter(p=>p.active&&!p.is_summary).sort((a,b)=>a.sort_order-b.sort_order);
const trim=s=>String(s||'').trim();
function notice(text,error=false){document.querySelector('.notice')?.remove();let d=document.createElement('div');d.className='notice'+(error?' error':'');d.setAttribute('role','status');d.textContent=text;document.body.append(d);setTimeout(()=>d.remove(),4400)}
function setBusy(yes){state.busy=yes;document.querySelectorAll('button[type=submit]').forEach(x=>x.disabled=yes)}
function signedIn(){return !!state.user||state.demo}
async function paged(table){let all=[];for(let from=0;from<50000;from+=1000){const {data,error}=await state.db.from(table).select('*').eq('owner_id',state.user.id).range(from,from+999);if(error)throw error;all.push(...(data||[]));if(!data||data.length<1000)break;}return all}
async function seedCatalog(){const current=await paged('procedure_catalog');const existing=new Set(current.map(p=>p.id));const missing=SEED.filter(p=>!existing.has(p.id));for(let i=0;i<missing.length;i+=60){const batch=missing.slice(i,i+60).map(p=>({...p,owner_id:state.user.id,historical_total:0,historical_success:p.outcome_applicable?0:null,halo:false,review_interval_days:null,sim_interval_days:null,active:true}));const {error}=await state.db.from('procedure_catalog').insert(batch);if(error)throw error;}}
async function refreshData(force=false){if(!state.user||(state.busy&&!force))return;if(!force&&Date.now()-state.lastSync<12000)return;try{const [catalog,entries]=await Promise.all([paged('procedure_catalog'),paged('procedure_entries')]);state.catalog=catalog.sort((a,b)=>a.sort_order-b.sort_order);state.entries=entries.sort(P.byDateDesc);state.metrics=P.computeMetrics(state.catalog,state.entries);state.lastSync=Date.now();render();}catch(err){notice('Could not synchronize: '+err.message,true)}}
async function beginSignedIn(user){if(!user)return;const changed=state.user?.id!==user.id;state.user=user;state.demo=false;if(changed){el.innerHTML='<div class="boot"><div class="loader"></div><p>Preparing your private procedure catalog…</p></div>';try{await seedCatalog();await refreshData(true);}catch(err){el.innerHTML='<div class="boot"><div><h2>Setup could not finish</h2><p>'+esc(err.message)+'</p><button class="btn primary" data-action="retry-load">Retry</button></div></div>';}}}
function startDemo(){state.demo=true;state.user=null;state.catalog=SEED.map(p=>({...p,historical_total:0,historical_success:p.outcome_applicable?0:null,halo:false,review_interval_days:null,sim_interval_days:null,active:true}));state.entries=[];state.metrics=P.computeMetrics(state.catalog,state.entries);state.view='overview';render();notice('Preview mode: changes are temporary and never uploaded.');}
function authPage(){const noConfig=!configured();el.innerHTML=`<div class="auth-wrap"><section class="auth-card">
 <div class="brandmark">⌁</div><h1>Procedure Tracker</h1><p>Clinical experience, outcome tracking, and HALO practice—organized in one place.</p>
 ${noConfig?`<div class="warn"><strong>Cloud configuration required.</strong><br>Enter your Supabase project URL and publishable key in <code>config.js</code>, then follow <code>SETUP.md</code>.<br><br>You can explore the interface without a database.</div><button class="btn primary" data-action="demo">Explore temporary preview</button>`:
 `<form id="auth-form"><div class="field"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" minlength="8" autocomplete="current-password" required></div><div class="checks"><label class="choice"><input type="radio" name="auth-mode" value="login" checked> Sign in</label><label class="choice"><input type="radio" name="auth-mode" value="signup"> Create account</label></div><button class="btn primary" type="submit">Continue securely</button></form>`}
 <p class="auth-sub">For institution-approved, nonidentifying professional logs only. The app never asks for names, medical record numbers, or other patient identifiers. Each record gets a random internal case code.</p></section></div>`;}
function syncBadge(){return state.demo?'<span class="pill soon">Temporary preview</span>':'<span class="pill ok">Private cloud sync</span>'}
const navs=[['overview','▦','Overview'],['log','⊕','Log'],['history','◷','History'],['practice','◎','Practice'],['settings','⚙','Settings']];
const viewTitles={overview:'Procedure overview',log:'Record procedure',history:'Procedure history',practice:'HALO practice',settings:'Settings & backup',detail:'Procedure detail'};
function scaffold(content){el.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">⌁</div><div><div class="brandtitle">Procedure Tracker</div><div class="brandsub">Proficiency & practice</div></div></div><nav class="nav" aria-label="Main navigation">${navs.map(([slug,icon,title])=>`<button data-nav="${slug}" class="${state.view===slug?'active':''}"><span class="navicon">${icon}</span>${title}</button>`).join('')}</nav><div class="sidebarfoot">${syncBadge()}<div style="margin-top:11px">${state.demo?'No account connected':'Signed in: '+esc(state.user?.email||'')}</div><button data-action="${state.demo?'exit-demo':'signout'}">${state.demo?'Exit preview':'Sign out'}</button></div></aside><div class="main"><header class="topbar"><div><div class="breadcrumb">My practice / ${esc(viewTitles[state.view])}</div><h1>${esc(viewTitles[state.view])}</h1></div><div class="top-actions">${syncBadge()}<button class="btn" data-action="refresh">↻ Refresh</button><button class="btn primary" data-nav="log">+ New entry</button></div></header><main class="content">${state.demo?'<div class="warn">Preview only—no records are stored or synchronized. Do not enter any patient-related information here.</div>':''}${content}</main></div><nav class="mobile-bar" aria-label="Mobile navigation">${navs.map(([slug,icon,title])=>`<button data-nav="${slug}" class="${state.view===slug?'active':''}"><span>${icon}</span>${title}</button>`).join('')}</nav></div>`}
function metricFor(p){return state.metrics.get(p.id)||{};}
function recentDisplay(m,p){if(!p.outcome_applicable)return 'N/A';if(!m.recentN)return '—';return `${pct(m.recentRate)} (${m.recentN}/10)`}
function overview(){const metrics=[...state.metrics.values()];const due=state.catalog.filter(p=>p.active&&p.halo).filter(p=>{const s=P.practiceStatus(p,metricFor(p),today());return s.review.state==='due'||s.simulation.state==='due'}).length;
 const clinical=state.entries.filter(e=>e.kind==='clinical').length;
 const supervised=state.entries.filter(e=>e.kind==='supervised').length;
 const active=state.catalog.filter(p=>p.active).length;
 const q=state.search.toLowerCase();const matches=state.catalog.filter(p=>p.active&&(state.overviewFilter!=='halo'||p.halo)&&(`${p.category} ${displayName(p)}`).toLowerCase().includes(q));
 return `<p class="sectionlead">A unified view of your clinical experience, current performance, and training needs.</p><div class="grid four"><div class="stat-card"><div class="stat-label">Tracked procedures</div><div class="stat-value mono">${fmt(active)}</div><div class="stat-foot">Across ${categories().length} categories</div></div><div class="stat-card"><div class="stat-label">New clinical logs</div><div class="stat-value mono">${fmt(clinical)}</div><div class="stat-foot">Since starting this application</div></div><div class="stat-card"><div class="stat-label">Supervised occurrences</div><div class="stat-value mono">${fmt(supervised)}</div><div class="stat-foot">Excluded from success statistics</div></div><div class="stat-card attention"><div class="stat-label">HALO procedures needing practice</div><div class="stat-value mono">${fmt(due)}</div><div class="stat-foot">Review and/or simulation due</div></div></div>
 <div class="section-head"><div><h2>Procedure catalog</h2><p>Historical totals and new entries are combined. One entry can contribute to multiple summary rows.</p></div><button class="btn compact" data-action="expand-all">Expand all</button></div><div class="toolbar"><input class="search" id="overview-search" type="search" placeholder="Search procedure, subtype, category…" value="${esc(state.search)}" aria-label="Search procedures"><span class="pill">${matches.length} procedures</span><button class="btn compact" data-action="show-halo">HALO only</button><button class="btn compact" data-action="show-all">Show all</button></div>
 ${categoryTables(matches,q)}</div>`;
}
function categoryTables(rows,q){
 const cats=[...new Set(rows.map(x=>x.category))];
 if(!cats.length)return '<div class="empty">No procedures match this search.</div>';
 return cats.map(cat=>{
  const procs=rows.filter(x=>x.category===cat),open=!!q||state.expanded.has(cat);
  const groups=[...new Set(procs.map(p=>p.procedure_group))];
  const row=p=>{const m=metricFor(p),s=P.practiceStatus(p,m,today()),warn=s.review.state==='due'||s.simulation.state==='due',soon=s.review.state==='soon'||s.simulation.state==='soon';
   return `<tr class="clickable ${p.is_summary?'summary-row':''}" data-proc="${esc(p.id)}"><td class="procedure-name"><button class="table-link name">${esc(p.variant||p.procedure_group)}</button>${p.is_summary?' <span class="pill summary">Rollup</span>':''}${p.halo?' <span class="pill halo">HALO</span>':''}</td><td class="mono">${fmt(m.total)}</td><td class="mono">${p.outcome_applicable?pct(m.overallRate):'N/A'}</td><td class="mono">${recentDisplay(m,p)}</td><td class="mono">${p.outcome_applicable?(m.firstN?pct(m.firstRate):'—'):'N/A'}</td><td class="nowrap">${shortDate(m.lastClinical)}</td><td>${p.halo?`<span class="pill ${warn?'due':soon?'soon':'ok'}">${warn?'Due':soon?'Soon':'Tracked'}</span>`:'—'}</td></tr>`;
  };
  const lines=groups.map(g=>{const matching=procs.filter(p=>p.procedure_group===g);return `<tr class="group-row"><td colspan="7">${esc(g)}</td></tr>${matching.map(row).join('')}`}).join('');
  return `<section class="category"><button class="category-title" data-category="${esc(cat)}" aria-expanded="${open}"><span><span class="chev">▸</span>&nbsp; ${esc(cat)}</span><span class="right">${procs.length} rows · ${groups.length} groups</span></button>${open?`<div class="table-wrap" style="border:0;border-radius:0"><table class="data-table"><thead><tr><th>Procedure / subtype</th><th>Volume</th><th>Overall</th><th>Recent 10</th><th>First attempt</th><th>Last clinical</th><th>Practice</th></tr></thead><tbody>${lines}</tbody></table></div>`:''}</section>`;
 }).join('');
}
function kindName(kind){return {clinical:'Clinical performance',supervised:'Supervised',review:'Intellectual review',simulation_low:'Low-fidelity simulation',simulation_high:'High-fidelity simulation'}[kind]||kind}
function kindPill(kind){return kind==='clinical'?'clinical':kind==='review'?'review':kind.startsWith('simulation_')?'sim':'summary'}
function caseTag(entry){return (entry.id||'').replaceAll('-','').slice(0,12).toUpperCase()}
function renderLog(){const e=state.editEntryId?state.entries.find(x=>x.id===state.editEntryId):null;const rows=nonSummaries();const primary=e?getProc(e.procedure_id):(getProc(state.preselectedId)||rows[0]);const cat=primary?.category||categories()[0];const kind=e?.kind||state.preselectedKind||'clinical';
 return `<p class="sectionlead">Log once, update every applicable category automatically. No patient-identifying fields are provided.</p><section class="panel" style="max-width:850px"><div class="section-head" style="margin-top:0"><h2>${e?'Edit existing entry':'New procedure record'}</h2><span class="pill">${e?'Case '+caseTag(e):'Unique case code generated on save'}</span></div><form id="log-form"><div class="form-grid"><div class="field wide"><label>Activity type</label><div class="checks" id="kind-options">${P.TYPES.map(k=>`<label class="choice"><input type="radio" name="kind" value="${k}" ${k===kind?'checked':''}> ${esc(kindName(k))}</label>`).join('')}</div></div><div class="field"><label for="performed_on">Date</label><input name="performed_on" id="performed_on" type="date" max="${today()}" value="${esc(e?.performed_on||today())}" required></div><div class="field"><label for="cat-select">Category</label><select id="cat-select" name="category">${categories().map(c=>`<option value="${esc(c)}" ${cat===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field wide"><label for="proc-select">Primary procedure</label><select name="procedure_id" id="proc-select" required>${options(rows.filter(p=>p.category===cat))}</select></div><div class="field wide" id="secondary-field"><label>Second central line classification <span class="hint">(optional site/type attribution for same encounter, not another procedure)</span></label><div class="multi-select" id="secondary-list"></div></div><div class="field" id="patient-field"><label for="patient-group">Age group for rollup statistics</label><select id="patient-group" name="patient_group"><option value="unspecified">Not specified</option><option value="adult">Adult</option><option value="pediatric">Pediatric</option></select><div class="hint">Used to attribute arterial and central vascular access to adult/pediatric totals.</div></div><div class="field" id="difficulty-field"><label for="difficulty">Perceived difficulty</label><select id="difficulty" name="difficulty"><option value="">Not rated</option><option value="1">1 · Very easy</option><option value="2">2 · Easy</option><option value="3">3 · Expected / moderate</option><option value="4">4 · Difficult</option><option value="5">5 · Very difficult</option></select></div><div class="field" id="first-field"><label for="first-attempt">Successful on first attempt?</label><select id="first-attempt" name="first_attempt_success"><option value="">Select…</option><option value="true">Yes</option><option value="false">No</option></select></div><div class="field" id="success-field"><label for="success">Successful overall?</label><select id="success" name="overall_success"><option value="">Select…</option><option value="true">Yes</option><option value="false">No</option></select></div><div class="field wide"><label for="notes">Learning notes <span class="hint">(optional; no identifying case details)</span></label><textarea id="notes" name="notes" maxlength="4000" placeholder="Technical challenges, lessons learned, or points to review…">${esc(e?.notes||'')}</textarea></div></div><div class="inline-info">Do not enter names, MRNs, encounter numbers, dates of birth, or identifying case details in the notes. A random event code is generated; it is not a patient identifier.</div><div class="form-actions"><span class="save-state">${e?'Changes replace the selected record':'Records synchronize to your private account'}</span><button type="button" class="btn" data-action="cancel-edit">Cancel</button><button type="submit" class="btn primary">${e?'Save changes':'Save procedure'}</button></div></form></section>`;
}
function primarySelection(){return state.editEntryId?state.entries.find(x=>x.id===state.editEntryId)?.procedure_id:state.preselectedId}
function initLogControls(){const e=state.editEntryId?state.entries.find(x=>x.id===state.editEntryId):null;
 const pro=document.getElementById('proc-select');if(!pro)return;
 if((e||state.preselectedId)&&getProc(primarySelection()))pro.value=primarySelection();
 document.getElementById('patient-group').value=e?.patient_group||'unspecified';
 document.getElementById('difficulty').value=e?.difficulty??'';
 document.getElementById('first-attempt').value=e?.first_attempt_success==null?'':String(e.first_attempt_success);
 document.getElementById('success').value=e?.overall_success==null?'':String(e.overall_success);
 updateSecondary(e?.additional_ids||[]);toggleLogFields();
}
function updateSecondary(selected){const proc=getProc(document.getElementById('proc-select')?.value);const slot=document.getElementById('secondary-list');if(!slot||!proc)return;const related=(proc.category==='Vascular Access'&&['Central Venous Access (Location)','Central Venous Access (Type)'].includes(proc.procedure_group))?nonSummaries().filter(p=>p.id!==proc.id&&p.category==='Vascular Access'&&['Central Venous Access (Location)','Central Venous Access (Type)'].includes(p.procedure_group)&&p.procedure_group!==proc.procedure_group).sort((a,b)=>a.sort_order-b.sort_order):[];
 slot.innerHTML=related.map(p=>`<label class="choice"><input type="checkbox" name="secondary_id" value="${esc(p.id)}" ${(selected||[]).includes(p.id)?'checked':''}>${esc(displayName(p))}</label>`).join('');
 document.getElementById('secondary-field').classList.toggle('hidden',!related.length);
}
function toggleLogFields(){const kind=document.querySelector('input[name=kind]:checked')?.value||'clinical';const proc=getProc(document.getElementById('proc-select')?.value);const clinical=kind==='clinical', sim=kind.startsWith('simulation');const outcome=proc?.outcome_applicable;
 document.getElementById('first-field')?.classList.toggle('hidden',!(clinical||sim)||!outcome);
 document.getElementById('success-field')?.classList.toggle('hidden',!(clinical||sim)||!outcome);
 document.getElementById('difficulty-field')?.classList.toggle('hidden',kind==='review');
 document.getElementById('patient-field')?.classList.toggle('hidden',!['clinical','supervised'].includes(kind)||proc?.category!=='Vascular Access'||!['Arterial Lines','Central Venous Access (Location)','Central Venous Access (Type)'].includes(proc?.procedure_group));
 const ff=document.getElementById('first-attempt'),s=document.getElementById('success');if(ff)ff.required=clinical&&outcome;if(s)s.required=clinical&&outcome;
}
function outcomeSpan(e){if(e.kind==='clinical'&&!getProc(e.procedure_id)?.outcome_applicable)return '<span class="muted">N/A outcomes</span>';return e.overall_success===true?'<span class="pill ok">Successful</span>':e.overall_success===false?'<span class="pill due">Unsuccessful</span>':'<span class="muted">Not scored</span>'}
function historyView(){const query=state.historySearch.toLowerCase(),entries=state.entries.filter(e=>`${displayName(getProc(e.procedure_id))} ${getProc(e.procedure_id)?.category||''} ${e.notes||''} ${kindName(e.kind)} ${caseTag(e)}`.toLowerCase().includes(query));return `<p class="sectionlead">Review your documented performances, simulations, supervision, and learning points.</p><div class="toolbar"><input class="search" id="history-search" type="search" value="${esc(state.historySearch)}" placeholder="Search activity, case code, or notes…"><span class="pill">${entries.length} entries</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Activity</th><th>Procedure</th><th>Difficulty</th><th>Outcome</th><th>Case code</th><th></th></tr></thead><tbody>${entries.length?entries.map(e=>{const p=getProc(e.procedure_id);return `<tr><td class="nowrap">${shortDate(e.performed_on)}</td><td><span class="pill ${kindPill(e.kind)}">${esc(kindName(e.kind))}</span></td><td><button class="table-link" data-proc="${esc(e.procedure_id)}"><span class="strong">${esc(displayName(p))}</span></button>${e.notes?`<div class="small muted truncate" style="max-width:280px">${esc(e.notes)}</div>`:''}</td><td>${e.difficulty||'—'}</td><td>${outcomeSpan(e)}</td><td class="mono small">${caseTag(e)}</td><td><button class="btn compact" data-edit-entry="${esc(e.id)}">Edit</button> <button class="btn compact danger" data-delete-entry="${esc(e.id)}">Delete</button></td></tr>`}).join(''):`<tr><td colspan="7" class="table-empty">No entries yet. Use the Log tab to record your first procedure.</td></tr>`}</tbody></table></div>`}
function dueClass(s){return s.state==='off'?'':s.state}
function practiceView(){const halo=state.catalog.filter(p=>p.active&&p.halo);const pairs=halo.map(p=>({p,m:metricFor(p),s:P.practiceStatus(p,metricFor(p),today())}));let filtered=pairs;
 if(state.practiceFilter==='due')filtered=pairs.filter(x=>x.s.review.state==='due'||x.s.simulation.state==='due');
 if(state.practiceFilter==='soon')filtered=pairs.filter(x=>x.s.review.state==='soon'||x.s.simulation.state==='soon');
 const dueCount=pairs.filter(x=>x.s.review.state==='due'||x.s.simulation.state==='due').length;
 return `<p class="sectionlead">Review and simulation are tracked independently. Clinical performance never silently resets either practice clock.</p><div class="grid three"><div class="stat-card"><div class="stat-label">HALO procedures</div><div class="stat-value mono">${halo.length}</div><div class="stat-foot">Designated by you</div></div><div class="stat-card attention"><div class="stat-label">Practice overdue or due</div><div class="stat-value mono">${dueCount}</div><div class="stat-foot">At least one practice track due</div></div><div class="stat-card"><div class="stat-label">Practice sessions logged</div><div class="stat-value mono">${state.entries.filter(e=>['review','simulation_low','simulation_high'].includes(e.kind)).length}</div><div class="stat-foot">Separate from clinical outcomes</div></div></div>
 <div class="section-head"><div><h2>HALO practice schedule</h2><p>Review and simulation dates are independently configurable per procedure.</p></div><button class="btn compact" data-nav="settings">Configure HALO procedures</button></div><div class="toolbar"><button class="btn compact ${state.practiceFilter==='all'?'primary':''}" data-practice-filter="all">All</button><button class="btn compact ${state.practiceFilter==='due'?'primary':''}" data-practice-filter="due">Due</button><button class="btn compact ${state.practiceFilter==='soon'?'primary':''}" data-practice-filter="soon">Upcoming</button></div><div class="panel">${filtered.length?filtered.map(({p,m,s})=>`<div class="practice-row"><div class="practice-left"><div class="strong"><button class="table-link" data-proc="${esc(p.id)}">${esc(displayName(p))}</button></div><div class="small muted">${esc(p.category)} · Last clinical: ${shortDate(m.lastClinical)}</div><div class="secondary-note">Intellectual: ${shortDate(m.lastReview)} · Simulation: ${shortDate(m.lastSimulation)}</div></div><div class="practice-right"><div class="two-line"><span class="cap">Intellectual review</span><span class="pill ${dueClass(s.review)}">${esc(s.review.label)}</span></div><div class="two-line"><span class="cap">Hands-on simulation</span><span class="pill ${dueClass(s.simulation)}">${esc(s.simulation.label)}</span></div><button class="btn compact" data-quick-log="review" data-for="${esc(p.id)}">+ Review</button><button class="btn compact" data-quick-log="simulation_low" data-for="${esc(p.id)}">+ Simulation</button></div></div>`).join(''):'<div class="empty"><strong>No matching HALO procedures</strong>Choose procedures and set their practice schedules in Settings.</div>'}</div>`;}
function detailView(){const p=getProc(state.detailId);if(!p){state.view='overview';return overview();}const m=metricFor(p),s=P.practiceStatus(p,m,today());const records=state.entries.filter(e=>P.computeAttribution(getProc(e.procedure_id),(e.additional_ids||[]).map(getProc).filter(Boolean),state.catalog,e.patient_group).includes(p.id)).sort(P.byDateDesc).slice(0,30);const last10=[...m.clinical].filter(e=>typeof e.overall_success==='boolean').sort(P.byDateDesc).slice(0,10);
 return `<button class="back" data-nav="overview">← Back to overview</button><div class="detail-top"><div><p class="eyebrow">${esc(p.category)}</p><h2 style="margin:0 0 6px;font-size:25px;letter-spacing:-.04em">${esc(displayName(p))}</h2><div class="checks">${p.is_summary?'<span class="pill summary">Summary / rollup</span>':''}${p.halo?'<span class="pill halo">HALO</span>':''}${!p.outcome_applicable?'<span class="pill">Success N/A</span>':''}</div></div><button class="btn primary" data-quick-log="clinical" data-for="${esc(p.id)}" ${p.is_summary?'disabled title="Select a specific subtype to record a clinical procedure"':''}>+ Log procedure</button></div><div class="grid four"><div class="stat-card"><div class="stat-label">All-time clinical volume</div><div class="stat-value">${fmt(m.total)}</div><div class="stat-foot">${fmt(m.historicalTotal)} historical + ${m.clinical.length} new</div></div><div class="stat-card"><div class="stat-label">All-time success</div><div class="stat-value">${p.outcome_applicable?pct(m.overallRate):'N/A'}</div><div class="stat-foot">${p.outcome_applicable?`${fmt(m.successes)} of ${fmt(m.knownSuccessN)}`:'Not success-scored'}</div></div><div class="stat-card"><div class="stat-label">Recent success</div><div class="stat-value">${p.outcome_applicable?pct(m.recentRate):'N/A'}</div><div class="stat-foot">${m.recentN||0} of 10 recent logs available</div></div><div class="stat-card"><div class="stat-label">First-attempt success</div><div class="stat-value">${p.outcome_applicable?pct(m.firstRate):'N/A'}</div><div class="stat-foot">${m.firstN} newly logged clinical entries</div></div></div>
 <div class="grid two" style="margin-top:17px"><section class="panel"><h2>Recent performance</h2><p class="small muted">Historical data did not preserve the sequence of encounters. Only new clinical logs appear here.</p><div class="outcomes">${last10.length?last10.map(e=>`<span class="outcome ${e.overall_success?'win':'fail'}" title="${esc(friendly(e.performed_on))}">${e.overall_success?'✓':'×'}</span>`).join(''):'<span class="muted small">No recent success data yet</span>'}</div><div class="setting-row"><span class="muted">Last performed clinically</span><span class="strong">${friendly(m.lastClinical)}</span></div><div class="setting-row"><span class="muted">Supervised</span><strong>${m.supervisedCount}</strong></div><div class="setting-row"><span class="muted">Intellectual reviews</span><strong>${m.reviewCount}</strong></div><div class="setting-row"><span class="muted">Simulation sessions</span><strong>${m.simulationCount}</strong></div></section>
 <section class="panel"><div class="section-head" style="margin-top:0"><h2>Practice schedule</h2><button class="btn compact" data-edit-proc="${esc(p.id)}">Configure</button></div>${p.halo?`<div class="setting-row"><span>Intellectual review</span><span class="pill ${dueClass(s.review)}">${esc(s.review.label)}</span></div><div class="setting-row"><span>Simulation</span><span class="pill ${dueClass(s.simulation)}">${esc(s.simulation.label)}</span></div><div class="setting-row"><span class="muted">Last review / simulation</span><span>${shortDate(m.lastReview)} / ${shortDate(m.lastSimulation)}</span></div><div class="checks" style="margin-top:17px"><button class="btn compact" data-quick-log="review" data-for="${esc(p.id)}" ${p.is_summary?'disabled':''}>+ Review</button><button class="btn compact" data-quick-log="simulation_low" data-for="${esc(p.id)}" ${p.is_summary?'disabled':''}>+ Simulation</button></div>`:'<div class="empty">Not currently designated as HALO. Configure it to set recurring practice intervals.</div>'}</section></div>
 <div class="section-head"><div><h2>Linked record history</h2><p>Includes records attributed to this subtype or its parent summary.</p></div></div><section class="panel">${records.length?`<div class="timeline">${records.map(e=>`<div class="timeline-item"><div class="timeline-title"><strong>${shortDate(e.performed_on)}</strong><span class="pill ${kindPill(e.kind)}">${esc(kindName(e.kind))}</span>${outcomeSpan(e)}<span class="small muted">${caseTag(e)}</span><button class="btn compact" data-edit-entry="${esc(e.id)}">Edit</button></div>${e.notes?`<p>${esc(e.notes)}</p>`:''}</div>`).join('')}</div>`:'<div class="empty">No individual records for this procedure yet.</div>'}</section>`;
}

function settingsView(){
 const q=state.settingsSearch.toLowerCase();
 const procs=state.catalog.filter(p=>`${p.category} ${displayName(p)}`.toLowerCase().includes(q));
 const editing=state.editProcedureId==='new'?null:getProc(state.editProcedureId);
 const showForm=state.editProcedureId==='new'||!!editing;
 const cats=categories();
 const procForm=showForm?`<section class="panel" id="procedure-editor" style="margin-bottom:20px"><div class="section-head" style="margin-top:0"><h2>${editing?'Edit procedure definition':'Add procedure'}</h2><button class="btn compact" type="button" data-action="close-proc-editor">Close</button></div><form id="procedure-form"><div class="form-grid">
 <div class="field"><label for="proc-category">Category</label><input id="proc-category" name="category" list="category-list" value="${esc(editing?.category||'')}" placeholder="Choose or type a category" maxlength="100" required><datalist id="category-list">${cats.map(c=>`<option value="${esc(c)}">`).join('')}</datalist></div>
 <div class="field"><label for="proc-group">Procedure / group name</label><input id="proc-group" name="procedure_group" value="${esc(editing?.procedure_group||'')}" maxlength="150" required></div>
 <div class="field"><label for="proc-variant">Subtype (optional)</label><input id="proc-variant" name="variant" value="${esc(editing?.variant||'')}" maxlength="150"></div>
 <div class="field"><label for="proc-active">Visibility</label><select name="active" id="proc-active"><option value="true" ${editing?.active!==false?'selected':''}>Active</option><option value="false" ${editing?.active===false?'selected':''}>Archived (records retained)</option></select></div>
 <div class="field"><label for="proc-scoring">Success metric</label><select name="outcome_applicable" id="proc-scoring"><option value="true" ${editing?.outcome_applicable!==false?'selected':''}>Success / failure applies</option><option value="false" ${editing?.outcome_applicable===false?'selected':''}>N/A (volume only)</option></select></div>
 <div class="field"><label for="proc-summary">Row type</label><select name="is_summary" id="proc-summary"><option value="false" ${!editing?.is_summary?'selected':''}>Directly loggable procedure</option><option value="true" ${editing?.is_summary?'selected':''}>Summary-only / rollup</option></select></div>
 <div class="field"><label for="proc-total">Historical performed (baseline)</label><input id="proc-total" name="historical_total" type="number" min="0" step="1" value="${editing?.historical_total??0}" required></div>
 <div class="field"><label for="proc-historical-success">Historical successful (baseline)</label><input id="proc-historical-success" name="historical_success" type="number" min="0" step="1" value="${editing?.historical_success??0}" ${editing?.outcome_applicable===false?'disabled':''}></div>
 <div class="field wide"><label class="choice"><input type="checkbox" id="proc-halo" name="halo" ${editing?.halo?'checked':''}> HALO: include in practice dashboard</label></div>
 <div class="field"><label for="proc-review-interval">Intellectual review interval (days)</label><input id="proc-review-interval" name="review_interval_days" type="number" min="1" max="36500" step="1" placeholder="Not scheduled" value="${editing?.review_interval_days??''}"></div>
 <div class="field"><label for="proc-sim-interval">Simulation interval (days)</label><input id="proc-sim-interval" name="sim_interval_days" type="number" min="1" max="36500" step="1" placeholder="Not scheduled" value="${editing?.sim_interval_days??''}"></div>
 <div class="field wide"><label>Additional summary rows to update when logging this subtype</label><div class="multi-select" style="max-height:140px">${state.catalog.filter(p=>p.is_summary&&p.id!==editing?.id).map(p=>`<label class="choice"><input type="checkbox" name="rollup_id" value="${esc(p.id)}" ${(editing?.rollup_ids||[]).includes(p.id)?'checked':''}>${esc(p.category)} / ${esc(displayName(p))}</label>`).join('')||'<span class="small muted">No summary rows configured</span>'}</div><span class="hint">Existing laryngoscopy and vaginal delivery subtype links are already preconfigured. Vascular age-group summaries are assigned from each entry's age group.</span></div>
 </div><div class="form-actions"><button class="btn" type="button" data-action="close-proc-editor">Cancel</button><button class="btn primary" type="submit">${editing?'Update procedure':'Add procedure'}</button></div></form></section>`:'';
 return `<p class="sectionlead">Customize classifications, success scoring, historical baselines, and independent HALO practice schedules. Records are never deleted when a procedure is archived.</p>
 <div class="grid two"><section class="panel"><h2>Private data & backups</h2><p class="small muted">Export a full JSON backup of your catalog, historical counts, training settings and procedure entries. Keep backup files in an appropriately protected location.</p><div class="checks"><button class="btn" data-action="backup-json">↓ Download JSON backup</button><button class="btn" data-action="export-csv">↓ Export entries CSV</button></div><div class="setting-row"><div><strong>Restore a backup</strong><div class="small muted">Merge by record ID (does not erase other records)</div></div><label class="btn compact" for="restore-input">Choose JSON…</label><input id="restore-input" type="file" accept=".json,application/json" hidden></div><div class="setting-row"><div><strong>Import your prior spreadsheet totals</strong><div class="small muted">Select the separately provided private historical-import.json file; does not invent dated cases.</div></div><label class="btn compact" for="history-import-input">Import totals…</label><input id="history-import-input" type="file" accept=".json,application/json" hidden></div></section>
 <section class="panel"><h2>Privacy & interpretation</h2><div class="setting-row"><span>Identifying patient fields</span><span class="pill ok">Not collected</span></div><div class="setting-row"><span>Encounter code</span><span class="strong">Random, per entry</span></div><div class="setting-row"><span>Last-10 statistics</span><span class="strong">New clinical logs only</span></div><div class="setting-row"><span>Historical dates / first-pass rate</span><span class="strong">Unavailable</span></div><p class="small muted">Dates and free-text notes could still reveal a patient if sufficient details are entered. Use only as permitted by institutional policy; avoid identifying descriptions and linkages.</p></section></div>
 <div class="section-head"><div><h2>Procedure catalog & HALO configuration</h2><p>${state.catalog.length} rows available, including summary rows.</p></div><button class="btn primary compact" data-action="add-proc">+ Add procedure</button></div>${procForm}
 <div class="toolbar"><input class="search" type="search" id="settings-search" placeholder="Find a procedure to configure…" value="${esc(state.settingsSearch)}"><span class="pill">${procs.length} rows</span></div><section class="panel"><div class="settings-rows">${procs.map(p=>{const m=metricFor(p);return `<div class="setting-row"><div class="left"><div class="strong">${esc(displayName(p))} ${p.halo?'<span class="pill halo">HALO</span>':''} ${p.is_summary?'<span class="pill summary">Rollup</span>':''} ${!p.active?'<span class="pill due">Archived</span>':''}</div><div class="small muted">${esc(p.category)} · ${m.total??0} clinical total · ${p.outcome_applicable?'Scored':'N/A success'}${p.halo?` · Intellectual ${p.review_interval_days||'—'}d / Simulation ${p.sim_interval_days||'—'}d`:''}</div></div><button class="btn compact" data-edit-proc="${esc(p.id)}">Edit</button></div>`}).join('')||'<div class="empty">No matching procedure definitions.</div>'}</div></section>`;
}
function render(){if(!signedIn()){authPage();return;}const contents={overview,log:renderLog,history:historyView,practice:practiceView,settings:settingsView,detail:detailView};scaffold((contents[state.view]||overview)());if(state.view==='log')initLogControls();if(state.view==='settings'&&state.editProcedureId)document.getElementById('proc-scoring')?.dispatchEvent(new Event('change'))}
function view(slug){if(slug==='log'){state.editEntryId=null;state.preselectedId=null;state.preselectedKind=null;}state.view=slug;render();window.scrollTo({top:0,behavior:'instant'});}
function renderKeepingFocus(selector,valueField){const control=document.querySelector(selector),cursor=control?.selectionStart;render();const next=document.querySelector(selector);if(next){next.focus();if(cursor!=null&&next.setSelectionRange)next.setSelectionRange(cursor,cursor)}}
function recalc(){state.entries.sort(P.byDateDesc);state.catalog.sort((a,b)=>a.sort_order-b.sort_order);state.metrics=P.computeMetrics(state.catalog,state.entries);state.lastSync=Date.now();render()}
async function saveRow(table,row){if(state.demo){const list=table==='procedure_entries'?state.entries:state.catalog;const ix=list.findIndex(x=>x.id===row.id);if(ix===-1)list.push({...row});else list[ix]={...list[ix],...row};return;}
 const {error}=await state.db.from(table).upsert({...row,owner_id:state.user.id},{onConflict:'owner_id,id'});if(error)throw error;
}
async function removeEntry(entryId){if(state.demo){state.entries=state.entries.filter(e=>e.id!==entryId);return;}const {error}=await state.db.from('procedure_entries').delete().eq('owner_id',state.user.id).eq('id',entryId);if(error)throw error;}
function optionalBool(s){return s==='true'?true:s==='false'?false:null}
function asNumberOrNull(x){return x==null||String(x).trim()===''?null:Number(x)}
async function submitLog(form){if(state.busy)return;const f=new FormData(form);const existing=state.entries.find(x=>x.id===state.editEntryId);const proc=getProc(f.get('procedure_id'));
 if(!proc||proc.is_summary||!proc.active)throw Error('Choose an active, directly loggable procedure.');
 const kind=String(f.get('kind')||'clinical');if(!P.TYPES.includes(kind))throw Error('Invalid activity type.');
 const date=String(f.get('performed_on')||'');if(!/^\d{4}-\d\d-\d\d$/.test(date)||date>today())throw Error('Select a valid procedure date that is not in the future.');
 const secondary=[...new Set(f.getAll('secondary_id').map(String))].filter(x=>x!==proc.id),validIds=new Set(state.catalog.map(x=>x.id));
 if(secondary.some(x=>!validIds.has(x)))throw Error('Invalid secondary classification.');
 const patientGroup=['adult','pediatric','unspecified'].includes(f.get('patient_group'))?f.get('patient_group'):'unspecified';
 const difficulty=kind==='review'?null:asNumberOrNull(f.get('difficulty'));
 let first=null,success=null;
 if(kind==='clinical'||kind.startsWith('simulation_')){if(proc.outcome_applicable){first=optionalBool(f.get('first_attempt_success'));success=optionalBool(f.get('overall_success'));if(kind==='clinical'&&(first===null||success===null))throw Error('Please record both first-attempt and overall outcome for clinical procedures.');if(first===true&&success!==true)throw Error('A first-attempt success must also be an overall success.');}}
 if(difficulty!==null&&(!Number.isInteger(difficulty)||difficulty<1||difficulty>5))throw Error('Difficulty must be 1–5.');
 const notes=trim(f.get('notes'));if(notes.length>4000)throw Error('Notes are too long.');
 const row={id:existing?.id||id(),procedure_id:proc.id,performed_on:date,kind,patient_group:patientGroup,difficulty,first_attempt_success:first,overall_success:success,notes:notes||null,additional_ids:secondary,attributed_ids:P.computeAttribution(proc,secondary.map(x=>getProc(x)),state.catalog,patientGroup)};
 setBusy(true);try{await saveRow('procedure_entries',row);state.editEntryId=null;state.preselectedId=null;state.preselectedKind=null;state.view='history';if(!state.demo){setBusy(false);await refreshData(true);}else{setBusy(false);recalc();}notice(existing?'Record updated.':'Procedure logged. Random case code: '+caseTag(row));}finally{setBusy(false)}
}
async function submitProcedure(form){if(state.busy)return;const f=new FormData(form);const existing=getProc(state.editProcedureId);
 const cat=trim(f.get('category')),group=trim(f.get('procedure_group')),variant=trim(f.get('variant'));
 if(!cat||!group)throw Error('Category and procedure name are required.');
 const total=Number(f.get('historical_total'));const applicable=f.get('outcome_applicable')==='true';const success=applicable?Number(f.get('historical_success')||0):null;
 if(!Number.isSafeInteger(total)||total<0||applicable&&(!Number.isSafeInteger(success)||success<0||success>total))throw Error('Historical counts must be whole numbers; successes cannot exceed performed.');
 const halo=f.has('halo');const review=asNumberOrNull(f.get('review_interval_days')),sim=asNumberOrNull(f.get('sim_interval_days'));
 for(const num of [review,sim])if(num!==null&&(!Number.isInteger(num)||num<1||num>36500))throw Error('Practice intervals must be whole days (1–36500).');
 const nextId=existing?.id||id();const rolls=[...new Set(f.getAll('rollup_id').map(String))].filter(x=>x!==nextId),validSummaries=new Set(state.catalog.filter(p=>p.is_summary).map(p=>p.id));if(rolls.some(x=>!validSummaries.has(x)))throw Error('Invalid rollup selection.');
 const row={id:nextId,category:cat,procedure_group:group,variant,is_summary:f.get('is_summary')==='true',outcome_applicable:applicable,historical_total:total,historical_success:success,sort_order:existing?.sort_order??Math.max(0,...state.catalog.map(p=>p.sort_order))+1,rollup_ids:rolls,halo,review_interval_days:halo?review:null,sim_interval_days:halo?sim:null,active:f.get('active')!=='false'};
 setBusy(true);try{await saveRow('procedure_catalog',row);state.editProcedureId=null;state.view='settings';setBusy(false);if(state.demo)recalc();else await refreshData(true);notice(existing?'Procedure updated.':'Procedure added.');}finally{setBusy(false)}
}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportBackup(){const payload={format:'procedure-tracker-backup-v1',exported_at:new Date().toISOString(),catalog:state.catalog.map(({owner_id,created_at,updated_at,...p})=>p),entries:state.entries.map(({owner_id,created_at,updated_at,...e})=>e)};
 download(`procedure-tracker-backup-${today()}.json`,JSON.stringify(payload,null,2),'application/json');notice('JSON backup saved. Store it securely.');}
function exportCsv(){const header=['case_code','date','activity','category','procedure','subtype','age_group','difficulty','first_attempt_success','overall_success','notes'];
 const row=e=>{const p=getProc(e.procedure_id);return [caseTag(e),e.performed_on,e.kind,p?.category||'',p?.procedure_group||'',p?.variant||'',e.patient_group||'',e.difficulty??'',e.first_attempt_success??'',e.overall_success??'',e.notes||''].map(x=>'"'+String(x).replace(/^([=+\-@\t\r])/,'\'$1').replaceAll('"','""')+'"').join(',')};
 download(`procedure-tracker-entries-${today()}.csv`,[header.join(','),...state.entries.map(row)].join('\r\n'),'text/csv;charset=utf-8');notice('CSV exported. Protect this file and its notes.');}
async function readJson(file){if(file.size>15*1024*1024)throw Error('File too large (15 MB maximum).');let parsed;try{parsed=JSON.parse(await file.text())}catch{throw Error('The selected file is not valid JSON.')}return parsed;}
function isUuid(s){return typeof s==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s)}
async function bulkUpsert(table,rows){for(let i=0;i<rows.length;i+=40){const batch=rows.slice(i,i+40).map(x=>({...x,owner_id:state.user.id}));const {error}=await state.db.from(table).upsert(batch,{onConflict:'owner_id,id'});if(error)throw error;}}
async function importHistorical(data){if(data?.format!=='procedure-tracker-historical-v1'||!Array.isArray(data.rows))throw Error('This is not the supplied historical totals import file.');
 if(data.rows.length!==SEED.length)throw Error('Unexpected historical import size: expected '+SEED.length+' procedure rows.');
 const map=new Map(data.rows.map(r=>[r.id,r]));if(map.size!==SEED.length)throw Error('Duplicate or missing historical procedure IDs.');
 const updated=state.catalog.filter(p=>map.has(p.id)).map(p=>{const incoming=map.get(p.id);if(!Number.isSafeInteger(incoming.historical_total)||incoming.historical_total<0)throw Error('Invalid historical totals.');if(p.outcome_applicable&&(!Number.isSafeInteger(incoming.historical_success)||incoming.historical_success<0||incoming.historical_success>incoming.historical_total))throw Error('Invalid historical successes.');return {...p,historical_total:incoming.historical_total,historical_success:p.outcome_applicable?incoming.historical_success:null};});
 if(updated.length!==SEED.length)throw Error('The spreadsheet import does not match the current procedure catalog.');
 const activeHistorical=updated.some(p=>{const previous=getProc(p.id);return previous?.historical_total>0||previous?.historical_success>0});
 if(activeHistorical&&!confirm('Historical counts are already present. Replace the baseline for these procedures with the imported totals? New dated records will remain unchanged.'))return;
 setBusy(true);try{if(state.demo)updated.forEach(p=>{const ix=state.catalog.findIndex(x=>x.id===p.id);state.catalog[ix]=p;});else await bulkUpsert('procedure_catalog',updated.map(({created_at,updated_at,...p})=>p));setBusy(false);if(state.demo)recalc();else await refreshData(true);notice(`Imported historical baselines for ${updated.length} procedure rows.`);}finally{setBusy(false)}
}
async function restoreBackup(data){if(data?.format!=='procedure-tracker-backup-v1'||!Array.isArray(data.catalog)||!Array.isArray(data.entries))throw Error('This is not a Procedure Tracker JSON backup.');
 if(data.catalog.length>2000||data.entries.length>30000)throw Error('This backup exceeds supported size limits.');
 const allowedCat=['id','category','procedure_group','variant','is_summary','outcome_applicable','historical_total','historical_success','sort_order','rollup_ids','halo','review_interval_days','sim_interval_days','active'];
 const allowedEntry=['id','procedure_id','performed_on','kind','patient_group','difficulty','first_attempt_success','overall_success','notes','additional_ids','attributed_ids'];
 const catalog=data.catalog.map(x=>Object.fromEntries(allowedCat.map(k=>[k,x[k]??null])));const entries=data.entries.map(x=>Object.fromEntries(allowedEntry.map(k=>[k,x[k]??null])));
 if(catalog.some(x=>!isUuid(x.id)||typeof x.category!=='string'||!x.category||typeof x.procedure_group!=='string'||!x.procedure_group||!Number.isSafeInteger(x.historical_total)||x.historical_total<0||!Array.isArray(x.rollup_ids)||x.historical_success!==null&&(!Number.isSafeInteger(x.historical_success)||x.historical_success>x.historical_total)))throw Error('Backup has invalid procedure definitions.');
 const allIDs=new Set([...state.catalog.map(p=>p.id),...catalog.map(x=>x.id)]);
 if(entries.some(x=>!isUuid(x.id)||!allIDs.has(x.procedure_id)||!P.TYPES.includes(x.kind)||!/^\d{4}-\d\d-\d\d$/.test(x.performed_on)||!Array.isArray(x.attributed_ids)||x.attributed_ids.some(a=>!allIDs.has(a))))throw Error('Backup has invalid procedure entries.');
 if(!confirm(`Merge ${catalog.length} catalog records and ${entries.length} activity records from this backup? Existing matching records will be updated. Other records will remain.`))return;
 setBusy(true);try{if(state.demo){for(const p of catalog){const i=state.catalog.findIndex(x=>x.id===p.id);if(i>=0)state.catalog[i]=p;else state.catalog.push(p);}for(const e of entries){const i=state.entries.findIndex(x=>x.id===e.id);if(i>=0)state.entries[i]=e;else state.entries.push(e);}}else{await bulkUpsert('procedure_catalog',catalog);await bulkUpsert('procedure_entries',entries)}setBusy(false);if(state.demo)recalc();else await refreshData(true);notice('Backup merged successfully.');}finally{setBusy(false)}
}
function showLog(idVal,kind){state.view='log';state.editEntryId=null;state.preselectedId=idVal;state.preselectedKind=kind;render();window.scrollTo(0,0);}
async function handleAction(action){switch(action){case 'demo':startDemo();break;case 'exit-demo':state.demo=false;state.user=null;state.catalog=[];state.entries=[];authPage();break;
 case 'retry-load':state.user=null;await beginSignedIn((await state.db.auth.getUser()).data.user);break;
 case 'signout':if(!confirm('Sign out of your private procedure tracker?'))return;await state.db.auth.signOut();state.user=null;authPage();break;
 case 'refresh':if(state.demo){notice('Preview data exists only on this page.');return}state.lastSync=0;await refreshData(true);notice('Data synchronized.');break;
 case 'expand-all':{const cats=categories();state.expanded=state.expanded.size===cats.length?new Set():new Set(cats);render();break;}
 case 'show-halo':state.overviewFilter='halo';render();break;case 'show-all':state.overviewFilter='all';state.search='';render();break;
 case 'cancel-edit':state.editEntryId=null;state.preselectedId=null;state.view='overview';render();break;
 case 'add-proc':state.editProcedureId='new';state.view='settings';render();document.getElementById('procedure-editor')?.scrollIntoView({behavior:'smooth'});break;
 case 'close-proc-editor':state.editProcedureId=null;render();break;
 case 'backup-json':exportBackup();break;case 'export-csv':exportCsv();break;
 }}
async function onClick(event){const t=event.target.closest('[data-nav],[data-proc],[data-category],[data-action],[data-edit-entry],[data-delete-entry],[data-edit-proc],[data-quick-log],[data-practice-filter]');if(!t)return;
 try{
 if(t.dataset.nav){view(t.dataset.nav);return;}
 if(t.dataset.action){await handleAction(t.dataset.action);return;}
 if(t.dataset.category){if(state.expanded.has(t.dataset.category))state.expanded.delete(t.dataset.category);else state.expanded.add(t.dataset.category);render();return;}
 if(t.dataset.editEntry){state.editEntryId=t.dataset.editEntry;state.view='log';state.preselectedId=null;state.preselectedKind=null;render();return;}
 if(t.dataset.deleteEntry){const e=state.entries.find(x=>x.id===t.dataset.deleteEntry);if(!e||!confirm(`Permanently delete ${kindName(e.kind)} on ${e.performed_on} (${caseTag(e)})? This will change statistics.`))return;setBusy(true);try{await removeEntry(e.id);setBusy(false);if(state.demo)recalc();else await refreshData(true);notice('Activity record deleted.')}finally{setBusy(false)}return;}
 if(t.dataset.editProc){state.editProcedureId=t.dataset.editProc;state.view='settings';render();document.getElementById('procedure-editor')?.scrollIntoView({behavior:'smooth'});return;}
 if(t.dataset.quickLog){showLog(t.dataset.for,t.dataset.quickLog);return;}
 if(t.dataset.practiceFilter){state.practiceFilter=t.dataset.practiceFilter;render();return;}
 if(t.dataset.proc){state.detailId=t.dataset.proc;state.view='detail';render();window.scrollTo(0,0);return;}
 }catch(err){notice(err.message||String(err),true)}
}
function onInput(e){if(e.target.id==='overview-search'){state.search=e.target.value;renderKeepingFocus('#overview-search');}
 else if(e.target.id==='history-search'){state.historySearch=e.target.value;renderKeepingFocus('#history-search');}
 else if(e.target.id==='settings-search'){state.settingsSearch=e.target.value;renderKeepingFocus('#settings-search');}}
function onChange(e){if(e.target.id==='cat-select'){const pro=document.getElementById('proc-select');const matches=nonSummaries().filter(p=>p.category===e.target.value);pro.innerHTML=options(matches);updateSecondary([]);toggleLogFields();}
 if(e.target.id==='proc-select'){updateSecondary([]);toggleLogFields();}
 if(e.target.closest('#kind-options'))toggleLogFields();
 if(e.target.id==='proc-scoring'){const field=document.getElementById('proc-historical-success');if(field){field.disabled=e.target.value!=='true';field.required=e.target.value==='true';}}
 if(e.target.id==='restore-input'&&e.target.files?.[0]){readJson(e.target.files[0]).then(restoreBackup).catch(err=>notice(err.message,true)).finally(()=>e.target.value='');}
 if(e.target.id==='history-import-input'&&e.target.files?.[0]){readJson(e.target.files[0]).then(importHistorical).catch(err=>notice(err.message,true)).finally(()=>e.target.value='');}}
async function onSubmit(e){if(!['log-form','procedure-form','auth-form'].includes(e.target.id))return;e.preventDefault();try{
 if(e.target.id==='log-form')await submitLog(e.target);
 else if(e.target.id==='procedure-form')await submitProcedure(e.target);
 else {if(!state.db)throw Error('Cloud authentication is not configured.');const f=new FormData(e.target),email=trim(f.get('email')),password=String(f.get('password')||'');const signup=f.get('auth-mode')==='signup';setBusy(true);try{let response=signup?await state.db.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}}):await state.db.auth.signInWithPassword({email,password});if(response.error)throw response.error;if(response.data?.user&&response.data?.session){await beginSignedIn(response.data.user);}else notice('Check your email for a confirmation link, then return to sign in.');}finally{setBusy(false)}}
 }catch(err){setBusy(false);notice(err.message||String(err),true)}}
async function bootstrap(){el.addEventListener('click',onClick);el.addEventListener('input',onInput);el.addEventListener('change',onChange);el.addEventListener('submit',onSubmit);
 if(!configured()){authPage();return;}
 if(!window.supabase?.createClient){el.innerHTML='<div class="auth-wrap"><div class="auth-card"><h1>Connection library unavailable</h1><p>Check internet connectivity and refresh. The database client could not load.</p><button class="btn" onclick="location.reload()">Retry</button></div></div>';return;}
 const config=window.PROCEDURE_APP_CONFIG;state.db=window.supabase.createClient(config.supabaseUrl,config.supabasePublishableKey,{auth:{autoRefreshToken:true,persistSession:true,detectSessionInUrl:true}});
 state.db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){state.user=null;state.catalog=[];state.entries=[];authPage();}else if(event==='SIGNED_IN'&&session?.user&&state.user?.id!==session.user.id){setTimeout(()=>beginSignedIn(session.user),0)}});
 try{const {data,error}=await state.db.auth.getSession();if(error)throw error;if(data?.session?.user)await beginSignedIn(data.session.user);else authPage();}catch(e){el.innerHTML='<div class="boot"><div><h2>Could not initialize</h2><p>'+esc(e.message)+'</p><button class="btn" onclick="location.reload()">Retry</button></div></div>';}
 window.addEventListener('focus',()=>{if(state.user&&!['log','settings'].includes(state.view))refreshData();});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.user&&!['log','settings'].includes(state.view))refreshData();});
}
bootstrap();
})();
